PTNT_HEAD = "<color=yellow>Nu\171i th\243<color>: "

function PTNT_IncErr(m)
	PTNT_INC_ERR = m
end

if Include then
	call(Include, { "\\script\\phongthan\\sinhhoat\\sh_lib.lua" }, "x", PTNT_IncErr)
	call(Include, { "\\script\\phongthan\\lib\\petexp_lib.lua" }, "x", PTNT_IncErr)
end
if PTLT_FOOD_EXP then PTNT_EXP_LTDON = PTLT_FOOD_EXP end

function PTNT_No()
end

function PTNT_Say(title, o)
	local n = getn(o)
	local t = { title, n }
	local k = 1
	while k <= n do t[k + 2] = o[k] k = k + 1 end
	call(Say, t)
end

-- bag + store box (HaveNormalItem)
function PTNT_Count(id)
	local n = HaveNormalItem(6, 1, id, -1)
	if n == nil then return 0 end
	return n
end

-- one unit from the bag (DelNormalItem takes one unit of a stack, bag only): 1 / 0
function PTNT_TakeOne(id)
	local r = DelNormalItem(6, 1, id, -1)
	if r and r > 0 then return 1 end
	return 0
end

-- n units of a magicscript item, joined to an existing stack when possible: number created
function PTNT_Give(id, n)
	local k = 0
	while k < n do
		local r = 0
		if AddNormalItemPile then r = AddNormalItemPile(6, 1, id, 1, 0, 0) else r = AddNormalItem(6, 1, id, 1, 0, 0) end
		if r == nil or r <= 0 then break end
		k = k + 1
	end
	return k
end

function PTNT_Free()
	if CalcFreeItemCellCount then
		local n = CalcFreeItemCellCount()
		if n == nil then return 0 end
		return n
	end
	return 10
end

function PTNT_Day()
	if PTSH_Day then return PTSH_Day() end
	local d = nil
	if date then d = tonumber(date("%Y%m%d")) end
	if d == nil then d = 0 end
	return d
end

function PTNT_Foods()
	local s = PTNT_Count(PTNT_I_LTDON) .. " Linh Th\243 \167\172n, " .. PTNT_Count(PTNT_I_LTDAI) .. " Linh Th\243 \167\185i \167\172n"
	if PTNT_IsDN() then s = s .. ", " .. PTNT_Count(PTNT_I_DTDON) .. " \167\214 T\246 Linh \167\172n" end
	return s
end

-- ---------------------------------------------------------------- linh thu
-- active linh thu (repairs a stale task 2389 like the Linh Thu Lenh does); 0 = none owned / system missing
function PTNT_LTActive()
	if PTLT_Stage == nil then return 0 end
	local k = GetTask(PTLT_T_ACT)
	if PTLT_Stage(k) > 0 then return k end
	k = 1
	while k <= 8 do
		if PTLT_Stage(k) > 0 then
			SetTask(PTLT_T_ACT, k)
			return k
		end
		k = k + 1
	end
	return 0
end

-- exp linh thu k still takes before its stage cap (level stage x 10)
function PTNT_LTRoom(k)
	local s = PTLT_Stage(k)
	if s <= 0 then return 0 end
	local r = PTLT_ExpFor(s * 10) - GetTask(PTLT_T_EXP0 + k)
	if r < 0 then r = 0 end
	return r
end

function PTNT_LTLine(k)
	local lv = PTLT_Level(k)
	local s = PTLT_Stage(k)
	local t = PTLT_Label(k)
	if lv >= s * 10 then
		if s < 4 then return t .. " (\174\199y c\202p, c\199n ti\213n h\227a)" end
		return t .. " (c\202p t\232i \174a)"
	end
	return t .. " (" .. (GetTask(PTLT_T_EXP0 + k) - PTLT_ExpFor(lv)) .. "/" .. PTLT_Need(lv) .. ")"
end

-- why linh thu k eats no more: evolve (stage 1..3) or the very last level (stage 4, level 40)
function PTNT_LTFullMsg(k)
	if PTLT_Stage(k) >= 4 then return "Linh th\243 \174\183 \174\185t c\202p t\232i \174a (giai \174o\185n 4, c\202p 40)." end
	return "Linh th\243 \174\183 \174\199y c\202p c\241a giai \174o\185n n\181y, h\183y t\215m Linh Th\243 S\248 (T\169y K\250, Tri\210u Ca) \174\211 ti\213n h\227a."
end

-- the summoned pet shows "Name [level]"
function PTNT_LTRefresh(k)
	local idx = PTLT_Owned()
	if idx > 0 and GetTask(PTLT_T_ACT) == k then SetNpcName(idx, PTLT_PET[k][1] .. " [" .. PTLT_Level(k) .. "]") end
end

function PTNT_LTNone()
	local s = "Ng\173\172i ch\173a c\227 linh th\243. G\198p Linh Th\243 S\248 \235 T\169y K\250 (1478/3060) ho\198c Tri\210u Ca (1763/3074) \174\211 nh\203n con \174\199u ti\170n mi\212n ph\221."
	if PTLT_Stage == nil then s = "H\214 linh th\243 ch\173a \174\173\238c c\181i tr\170n m\184y ch\241." end
	Say(PTNT_HEAD .. s, 2, "Quay l\185i/PTNT_Main", "\167\227ng/PTNT_No")
end

-- feed up to n units of item id (per exp each) to linh thu k, never past the stage cap: eaten, exp gained
function PTNT_LTFeed(k, id, per, n)
	local done = 0
	local gain = 0
	while done < n and PTNT_LTRoom(k) > 0 do
		if PTNT_TakeOne(id) < 1 then break end
		gain = gain + PTLT_AddExp(k, per)
		done = done + 1
	end
	if done > 0 then PTNT_LTRefresh(k) end
	return done, gain
end

function PTNT_LTMenu()
	local k = PTNT_LTActive()
	if k <= 0 then
		PTNT_LTNone()
		return
	end
	local o = {}
	tinsert(o, "Cho \168n 1 Linh Th\243 \167\172n (+30)/PTNT_LT1")
	tinsert(o, "Cho \168n 10 Linh Th\243 \167\172n (+300)/PTNT_LT10")
	tinsert(o, "Cho \168n 1 Linh Th\243 \167\185i \167\172n (+300)/PTNT_LTD1")
	tinsert(o, "\161n \174\213n \174\199y c\202p giai \174o\185n/PTNT_LTFill")
	tinsert(o, "Quay l\185i/PTNT_Main")
	tinsert(o, "\167\227ng/PTNT_No")
	PTNT_Say(PTNT_HEAD .. "Linh th\243 hi\214n t\185i: <color=yellow>" .. PTNT_LTLine(k) .. "<color>. C\223n nh\203n \174\173\238c " .. PTNT_LTRoom(k) .. " kinh nghi\214m tr\173\237c gi\237i h\185n giai \174o\185n. \167ang c\227: " .. PTNT_Foods() .. ". Ch\216 l\202y \174\229 trong h\181nh trang. \167\230i linh th\243 b\187ng Linh Th\243 L\214nh.", o)
end

-- after feeding: message and the menu again, or why nothing was eaten
function PTNT_LTDone(k, nd, ns, gain)
	if nd + ns <= 0 then
		local why = "Kh\171ng c\227 th\248c \168n ph\239 h\238p trong h\181nh trang. Nh\203n th\248c \168n m\231i ng\181y \235 menu Nu\171i th\243, L\212 Quan ho\198c Sinh Ho\185t S\173."
		if PTNT_LTRoom(k) <= 0 then why = PTNT_LTFullMsg(k) end
		Say(PTNT_HEAD .. why, 2, "Quay l\185i/PTNT_LTMenu", "\167\227ng/PTNT_No")
		return
	end
	Msg2Player("Linh th\243 \168n " .. ns .. " Linh Th\243 \167\172n, " .. nd .. " Linh Th\243 \167\185i \167\172n: +" .. gain .. " kinh nghi\214m. " .. PTNT_LTLine(k) .. ".")
	PTNT_LTMenu()
end

function PTNT_LTSmall(n)
	local k = PTNT_LTActive()
	if k <= 0 then
		PTNT_LTNone()
		return
	end
	local a, g = PTNT_LTFeed(k, PTNT_I_LTDON, PTNT_EXP_LTDON, n)
	PTNT_LTDone(k, 0, a, g)
end

function PTNT_LT1() PTNT_LTSmall(1) end
function PTNT_LT10() PTNT_LTSmall(10) end

function PTNT_LTD1()
	local k = PTNT_LTActive()
	if k <= 0 then
		PTNT_LTNone()
		return
	end
	local a, g = PTNT_LTFeed(k, PTNT_I_LTDAI, PTNT_EXP_LTDAI, 1)
	PTNT_LTDone(k, a, 0, g)
end

-- big food while it fits completely, then the small one, then one big more if a little room is left
function PTNT_LTFill()
	local k = PTNT_LTActive()
	if k <= 0 then
		PTNT_LTNone()
		return
	end
	local a, ga = PTNT_LTFeed(k, PTNT_I_LTDAI, PTNT_EXP_LTDAI, floor(PTNT_LTRoom(k) / PTNT_EXP_LTDAI))
	local b, gb = PTNT_LTFeed(k, PTNT_I_LTDON, PTNT_EXP_LTDON, 9999)
	local c = 0
	local gc = 0
	if PTNT_LTRoom(k) > 0 then c, gc = PTNT_LTFeed(k, PTNT_I_LTDAI, PTNT_EXP_LTDAI, 1) end
	PTNT_LTDone(k, a + c, b, ga + gb + gc)
end

-- ---------------------------------------------------------------- de tu (Di Nhan)
function PTNT_IsDN()
	if PTPE_Level == nil then return nil end
	if GetProfession() == PTNT_PROF_DN then return 1 end
	return nil
end

-- exp still needed to reach level 10
function PTNT_DTRoom()
	local lv = PTPE_Level()
	if lv >= PTPE_MAXLV then return 0 end
	local r = 0
	local l = lv
	while l < PTPE_MAXLV do
		r = r + PTPE_Need(l)
		l = l + 1
	end
	r = r - GetTask(PTPE_T_EXP)
	if r < 0 then r = 0 end
	return r
end

function PTNT_DTLine()
	local lv = PTPE_Level()
	if lv >= PTPE_MAXLV then return "\167\214 t\246 c\202p " .. lv .. " (c\202p t\232i \174a)" end
	return "\167\214 t\246 c\202p " .. lv .. ", kinh nghi\214m " .. GetTask(PTPE_T_EXP) .. "/" .. PTPE_Need(lv)
end

function PTNT_DTNone()
	Say(PTNT_HEAD .. "Ch\216 ph\184i D\222 Nh\169n c\227 \174\214 t\246 (g\228i b\187ng L\214nh B\181i Tri\214u H\229i).", 2, "Quay l\185i/PTNT_Main", "\167\227ng/PTNT_No")
end

function PTNT_DTFeed(n)
	local done = 0
	while done < n and PTNT_DTRoom() > 0 do
		if PTNT_TakeOne(PTNT_I_DTDON) < 1 then break end
		PTPE_AddExp(PTNT_EXP_DTDON)
		done = done + 1
	end
	return done
end

