	end
	local o = {}
	tinsert(o, "Cho \168n 1 \167\214 T\246 Linh \167\172n (+1000)/PTNT_DT1")
	tinsert(o, "Cho \168n 10 \167\214 T\246 Linh \167\172n (+10000)/PTNT_DT10")
	tinsert(o, "\161n \174\213n c\202p t\232i \174a (10)/PTNT_DTFill")
