	tinsert(o, "\167\227ng/PTNT_No")
	PTNT_Say(PTNT_HEAD .. "<color=yellow>" .. PTNT_DTLine() .. "<color>. C\199n th\170m " .. PTNT_DTRoom() .. " kinh nghi\214m \174\211 \174\185t c\202p 10. \167ang c\227 " .. PTNT_Count(PTNT_I_DTDON) .. " \167\214 T\246 Linh \167\172n (ch\216 l\202y \174\229 trong h\181nh trang). \167\214 t\246 c\223n nh\203n kinh nghi\214m khi c\239ng ch\241 \174\184nh qu\184i.", o)
end

function PTNT_DTDo(n)
	if not PTNT_IsDN() then
		PTNT_DTNone()
		return
	end
	local d = PTNT_DTFeed(n)
	if d <= 0 then
		local why = "Kh\171ng c\227 \167\214 T\246 Linh \167\172n trong h\181nh trang. Nh\203n th\248c \168n m\231i ng\181y \235 menu Nu\171i th\243."
		if PTNT_DTRoom() <= 0 then why = "\167\214 t\246 \174\183 \174\185t c\202p t\232i \174a (10)." end
		Say(PTNT_HEAD .. why, 2, "Quay l\185i/PTNT_DTMenu", "\167\227ng/PTNT_No")
		return
	end
	Msg2Player("\167\214 t\246 \168n " .. d .. " \167\214 T\246 Linh \167\172n: +" .. (d * PTNT_EXP_DTDON) .. " kinh nghi\214m. " .. PTNT_DTLine() .. ".")
	PTNT_DTMenu()
end

function PTNT_DT1() PTNT_DTDo(1) end
