-- ---------------------------------------------------------------- daily food
function PTNT_ClaimLeft()
	if GetTask(PTNT_T_DAY) == PTNT_Day() then return nil end
	return 1
end

function PTNT_Claim()
	if not PTNT_ClaimLeft() then
		Say(PTNT_HEAD .. "H\171m nay ng\173\172i \174\183 nh\203n th\248c \168n r\229i, ng\181y mai h\183y quay l\185i.", 2, "Quay l\185i/PTNT_Main", "\167\227ng/PTNT_No")
		return
	end
	local kinds = 1
	if PTNT_IsDN() then kinds = 2 end
	if PTNT_Free() < kinds then
		Say(PTNT_HEAD .. "H\181nh trang c\199n \221t nh\202t " .. kinds .. " \171 tr\232ng \174\211 nh\203n th\248c \168n.", 2, "Quay l\185i/PTNT_Main", "\167\227ng/PTNT_No")
		return
	end
	local a = PTNT_Give(PTNT_I_LTDON, PTNT_CLAIM_LT)
	local b = 0
	if kinds == 2 then b = PTNT_Give(PTNT_I_DTDON, PTNT_CLAIM_DT) end
	if a + b <= 0 then
		Say(PTNT_HEAD .. "Kh\171ng ph\184t \174\173\238c th\248c \168n (h\181nh trang \174\199y ho\198c m\184y ch\241 ch\173a c\181i v\203t ph\200m m\237i).", 2, "Quay l\185i/PTNT_Main", "\167\227ng/PTNT_No")
		return
	end
	SetTask(PTNT_T_DAY, PTNT_Day())
	local s = "\167\183 nh\203n th\248c \168n h\171m nay: " .. a .. " Linh Th\243 \167\172n"
	if kinds == 2 then
		s = s .. ", " .. b .. " \167\214 T\246 Linh \167\172n"
		if b < PTNT_CLAIM_DT then s = s .. " (thi\213u " .. (PTNT_CLAIM_DT - b) .. ": m\184y ch\241 ch\173a c\181i v\203t ph\200m m\237i ho\198c h\181nh trang \174\199y)" end
	end
	Msg2Player(s .. ".")
	PTNT_Main()
end

