end

function PTNT_Status()
	local s = PTNT_HEAD .. "tr\185ng th\184i th\243 c\241a ng\173\172i"
	local n = 0
	if PTLT_Stage then
		local act = GetTask(PTLT_T_ACT)
		local k = 1
		while k <= 8 do
			if PTLT_Stage(k) > 0 then
				s = s .. "\n" .. PTNT_LTLine(k)
				if k == act then s = s .. " [\174ang d\239ng]" end
				n = n + 1
			end
			k = k + 1
		end
	end
	if n == 0 then s = s .. "\nCh\173a c\227 linh th\243 (Linh Th\243 S\248 \235 T\169y K\250, Tri\210u Ca t\198ng con \174\199u ti\170n)." end
	if PTNT_IsDN() then s = s .. "\n" .. PTNT_DTLine() .. "." end
	s = s .. "\nTh\243 c\173\236i: kh\171ng c\199n cho \168n."
	s = s .. "\nTh\248c \168n \174ang c\227: " .. PTNT_Foods() .. "."
	Say(s, 2, "Quay l\185i/PTNT_Main", "\167\227ng/PTNT_No")
end

-- ---------------------------------------------------------------- right click of the food items
-- consumed only when it helps (not at the stage cap / level 10)
function PTNT_UseDT(it)
	if not PTNT_IsDN() then
		Say(PTNT_HEAD .. "\167\214 T\246 Linh \167\172n ch\216 d\181nh cho \174\214 t\246 c\241a ph\184i D\222 Nh\169n.", 1, "\167\227ng/PTNT_No")
		return 0
	end
	if PTNT_DTRoom() <= 0 then
		Say(PTNT_HEAD .. "\167\214 t\246 \174\183 \174\185t c\202p t\232i \174a (10).", 1, "\167\227ng/PTNT_No")
		return 0
	end
	RemoveItem(it, 1, 0)
	PTPE_AddExp(PTNT_EXP_DTDON)
	Msg2Player("\167\214 t\246 nh\203n " .. PTNT_EXP_DTDON .. " kinh nghi\214m. " .. PTNT_DTLine() .. ".")
	return 0
end

function PTNT_UseLTDai(it)
	local k = PTNT_LTActive()
	if k <= 0 then
		Say(PTNT_HEAD .. "Ng\173\172i ch\173a c\227 linh th\243. G\198p Linh Th\243 S\248 \235 T\169y K\250 ho\198c Tri\210u Ca.", 1, "\167\227ng/PTNT_No")
		return 0
	end
	if PTNT_LTRoom(k) <= 0 then
		Say(PTNT_HEAD .. PTNT_LTFullMsg(k), 1, "\167\227ng/PTNT_No")
		return 0
	end
	RemoveItem(it, 1, 0)
	local g = PTLT_AddExp(k, PTNT_EXP_LTDAI)
	PTNT_LTRefresh(k)
	Msg2Player("Linh th\243 nh\203n " .. g .. " kinh nghi\214m. " .. PTNT_LTLine(k) .. ".")
	return 0
end

-- ---------------------------------------------------------------- web admin (bridge, servertimer state)
-- mode 1 "cho an day": every owned linh thu to the cap of its stage, the Di Nhan pet +1 level.
-- mode 2 "tang cap toi da": every owned linh thu to stage 4 level 40, the Di Nhan pet to level 10.
-- current PlayerIndex: returns a short ASCII log text
function PTNT_AdmApply(mode)
	local log = "mode " .. mode
	local nlt = 0
	if PTLT_Stage then
		local act = GetTask(PTLT_T_ACT)
		local was = PTLT_Owned()
		local restage = 0
		local k = 1
		while k <= 8 do
			local s = PTLT_Stage(k)
			if s > 0 then
				if mode == 2 and s < 4 then
					PTLT_SetStage(k, 4)
					s = 4
					if k == act then restage = 1 end
				end
				SetTask(PTLT_T_EXP0 + k, PTLT_ExpFor(s * 10))
				log = log .. " lt" .. k .. "=s" .. s .. "/lv" .. PTLT_Level(k)
				nlt = nlt + 1
			end
			k = k + 1
		end
		if was > 0 then
			if restage == 1 then PTLT_Summon() else PTNT_LTRefresh(act) end
		end
	end
	if nlt == 0 then log = log .. " lt=none" end
	local dt = nil
	if PTNT_IsDN() then
		local lv = PTPE_Level()
		if lv < PTPE_MAXLV then
			if mode == 2 then
				PTPE_AddExp(PTNT_DTRoom())
			else
				local need = PTPE_Need(lv) - GetTask(PTPE_T_EXP)
				if need < 1 then need = 1 end
				PTPE_AddExp(need)
			end
		end
		dt = PTPE_Level()
		log = log .. " dt=lv" .. dt
	end
	local m = "Admin cho th\243 \168n \174\199y: "
	if mode == 2 then m = "Admin t\168ng c\202p th\243 t\232i \174a: " end
	if nlt > 0 then
		if mode == 2 then m = m .. "m\228i linh th\243 l\170n giai \174o\185n 4 c\202p 40" else m = m .. "m\228i linh th\243 l\170n \174\199y c\202p giai \174o\185n" end
	else
		m = m .. "ch\173a c\227 linh th\243"
	end
	if dt then m = m .. ", \174\214 t\246 c\202p " .. dt end
	Msg2Player(m .. ".")
	return log
end

function PTNT_AdminFeed(id, name, mode)
	local pi = nil
	if PTAdm_FindPlayer then pi = PTAdm_FindPlayer(name) end
	if not pi then
		if PTAdm_Log then PTAdm_Log(id, "FAIL", "offline " .. name) end
		return 0
	end
	if mode ~= 2 then mode = 1 end
	local txt = PTNT_AdmApply(mode)
	if PTAdm_Log then PTAdm_Log(id, "OK", name .. " " .. txt) end
	PlayerIndex = nil
	return 1
end
